function value(k,v,resource=page){if(v===null||v===undefined)return '—';if(k==='status'||k==='role')return badge(v);if((k==='customer'||k==='location')&&typeof v==='object')return `<span class="who">${escape(v.name||tr('(no name)','(بدون اسم)'))}${v.email?`<small>${escape(k==='location'&&v.email.startsWith('Home charger')?v.email.replace('Home charger',tr('Home charger','شاحن منزلي')):v.email)}</small>`:''}</span>`;if(k==='seller_type'&&sellerTypes[v])return escape(tr(...sellerTypes[v]));if(k==='kind'&&kindNames[v])return escape(tr(...kindNames[v]));if(typeof v==='boolean')return escape(v?tr('Yes','نعم'):tr('No','لا'));if(k==='commission_bps')return `${Number(v)/100}%`;if(resource==='cafe_orders'&&['total','unit_price'].includes(k))return escape(Number(v).toFixed(3)+' OMR');if(k==='order_no')return `<span class="ref">#${escape(Number(v)%1000)}</span>`;if(['total','refunded_total','quoted_price','delivery_fee','unit_price'].includes(k)||(resource==='settlements'&&k==='amount'))return escape(money(v));if(k.endsWith('_at')&&typeof v==='string')return escape(new Date(v).toLocaleString(lang==='ar'?'ar-OM':'en-GB'));if(typeof v==='object')return escape(Array.isArray(v)?v.map(x=>typeof x==='object'?Object.entries(x).map(([k,v])=>`${label(k)}: ${v}`).join(' · '):x).join('\n'):Object.entries(v).map(([k,v])=>`${label(k)}: ${v}`).join('\n'));return escape(v);}
async function api(path,method='GET',body){const res=await fetch('/api/dashboard'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=res.status===204?null:await res.json();if(!res.ok){if(res.status===401&&path!=='/login')showLogin();throw new Error(data?.error?.message||`${res.status}`);}return data;}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,4000);}
function showLogin(){user=null;$('workspace').hidden=true;$('login').hidden=false;$('detail-dialog').close();$('action-dialog').close();}
