  $('detail-body').querySelectorAll('[data-refund]').forEach(b=>b.onclick=async()=>{try{await api(`/ops/cafe/admin/orders/${b.dataset.refund}/refund`,'POST',{});again();}catch(e){toast(e.message);}});
