function renderSettings(data){const rows=Array.isArray(data)?data:Object.entries(data||{}).map(([key,value])=>({key,value}));$('page').innerHTML=`<div class="permission">${tr('Only super admins can change platform settings and administrator access. Changes apply to the whole platform.','يمكن للمدير العام فقط تغيير إعدادات المنصة وصلاحيات الإدارة. تنطبق التغييرات على المنصة بأكملها.')}</div><section class="panel"><div class="panel-heading"><h2>${title('settings')}</h2></div>${table(rows,['key','value'],'',false)}</section><div class="action-row"><button class="primary" id="edit-setting">${tr('Edit setting','تعديل إعداد')}</button><button class="secondary" id="overstay-setting">${tr('Overstay settings','إعدادات التأخر')}</button><button class="secondary" id="mobile-setting">${tr('Mobile charging settings','إعدادات الشحن المتنقل')}</button></div>`;
 $('edit-setting').onclick=()=>showAction(tr('Platform setting','إعداد المنصة'),[input('key',tr('Setting','الإعداد'),'select',rows[0]?.key,rows.map(r=>[r.key,r.key])),input('value',tr('Value','القيمة'))],b=>api('/ops/superadmin/settings','PUT',b));
 $('overstay-setting').onclick=async()=>{try{const r=await api('/ops/superadmin/overstay-settings');showAction(tr('Overstay settings','إعدادات التأخر'),Object.keys(r).map(k=>input(k,k.replaceAll('_',' '),'number',r[k])),b=>api('/ops/superadmin/overstay-settings','PUT',b));}catch(e){toast(e.message);}};
 $('mobile-setting').onclick=async()=>{try{const r=await api('/ops/superadmin/mobile-settings');showAction(tr('Mobile charging settings','إعدادات الشحن المتنقل'),Object.keys(r).map(k=>input(k,k.replaceAll('_',' '),typeof r[k]==='boolean'?'checkbox':'number',r[k])),b=>api('/ops/superadmin/mobile-settings','PUT',b));}catch(e){toast(e.message);}};
}
$('login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('login-error').textContent='';try{const form=new FormData(e.target);user=await api('/login','POST',{email:form.get('email'),password:form.get('password')});e.target.reset();showWorkspace();}catch(e){$('login-error').textContent=e.message;}finally{button.disabled=false;}};
$('action-form').onsubmit=async e=>{e.preventDefault();if(!action)return;$('action-submit').disabled=true;$('action-error').textContent='';try{const form=new FormData(e.target);const body=Object.fromEntries(action.fields.map(f=>[f.name,f.type==='checkbox'?form.has(f.name):f.type==='number'?(form.get(f.name)===''?null:Number(form.get(f.name))):String(form.get(f.name)||'')]));await action.submit(body);$('action-dialog').close();toast(tr('Changes saved.','تم حفظ التغييرات.'));await renderPage();if(currentDetail&&$('detail-dialog').open)await details(currentDetail.resource,currentDetail.id);}catch(e){$('action-error').textContent=e.message;}finally{$('action-submit').disabled=false;}};
$('close-detail').onclick=()=>{$('detail-dialog').close();currentDetail=null;};$('close-action').onclick=()=>$('action-dialog').close();
$('refresh').onclick=()=>void renderPage();$('language').onclick=()=>{lang=lang==='en'?'ar':'en';localStorage.setItem('gowatt-dashboard-language',lang);showWorkspace();};
$('logout').onclick=async()=>{try{await api('/logout','POST',{});showLogin();}catch(e){toast(e.message);}};
window.addEventListener('hashchange',()=>{offset=0;search='';if(!keepFilters)filters={};keepFilters=false;if(user)void renderPage();});
api('/session').then(data=>{user=data;showWorkspace();}).catch(()=>showLogin());

// ── Notifications (bell) ─────────────────────────────────────────────────
// Same inbox as the app: new seller applications, listings to review, etc.
// A notification with data.page opens that section, pre-filtered.
const noteText=n=>lang==='ar'&&n.data?.title_ar?[n.data.title_ar,n.data.body_ar||n.body]:[n.title,n.body];
async function refreshBell(){if(!user)return;try{const r=await api('/notifications/unread-count');const el=$('bell-count');el.textContent=r.count>99?'99+':String(r.count);el.hidden=!r.count;}catch{}}
async function openInbox(){$('detail-title').textContent=tr('Notifications','الإشعارات');$('detail-body').innerHTML='<div class="loading"></div>';if(!$('detail-dialog').open)$('detail-dialog').showModal();
 try{const r=await api('/notifications?limit=50');const items=r.notifications||[];
  $('detail-body').innerHTML=items.length?`<div class="inbox">${items.map((n,i)=>{const [t,b]=noteText(n);return `<button class="inbox-item ${n.read_at?'':'unread'}" data-note="${i}"><strong>${escape(t)}</strong><span>${escape(b)}</span><small>${escape(new Date(n.created_at).toLocaleString(lang==='ar'?'ar-OM':'en-GB'))}</small></button>`;}).join('')}</div>`:`<div class="empty">${tr('No notifications yet.','لا توجد إشعارات بعد.')}</div>`;
  $('detail-body').querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{const n=items[Number(b.dataset.note)];if(!n.data?.page)return;$('detail-dialog').close();openFiltered(n.data.page,n.data.filter||{});});
  if(items.some(n=>!n.read_at)){await api('/notifications/read-all','POST',{});refreshBell();}
 }catch(e){$('detail-body').innerHTML=`<p class="error">${escape(e.message)}</p>`;}}
$('bell').onclick=()=>void openInbox();
setInterval(()=>void refreshBell(),60000);
const _renderNavigation=renderNavigation;renderNavigation=function(){_renderNavigation();void refreshBell();};

// ── Freshness: "Updated" stamp, quiet auto-refresh on the overview, "/" to search ──
function stamp(){const el=$('updated');if(el)el.textContent=tr('Updated ','آخر تحديث ')+new Date().toLocaleTimeString(lang==='ar'?'ar-OM':'en-GB',{hour:'2-digit',minute:'2-digit'});}
setInterval(()=>{if(user&&['overview','cafes'].includes(page)&&!document.hidden&&!$('detail-dialog').open&&!$('action-dialog').open)void renderPage();},60000);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&$('search-records')){e.preventDefault();$('search-records').focus();}});
